#include <USB.h>
#include <USBHIDKeyboard.h>

USBHIDKeyboard Keyboard;

void setup() {
  USB.begin();
  Keyboard.begin();
  delay(3000);

  Keyboard.press(KEY_LEFT_ALT);
  Keyboard.press(KEY_LEFT_SHIFT);
  delay(20);
  Keyboard.releaseAll();
  delay(60);

  Keyboard.press(KEY_LEFT_GUI);
  Keyboard.press('r');
  delay(40);
  Keyboard.releaseAll();
  delay(600);

  Keyboard.print("shutdown /s /t 5");
  delay(100);

  Keyboard.press(KEY_RETURN);
  delay(30);
  Keyboard.release(KEY_RETURN);
}

void loop() {
}
